  const root=()=>document.querySelector('#costingContent'),status=()=>document.querySelector('#costingStatus'),canWrite=()=>practice||OracleDb.isDemo||OracleDb.permission('products.write');
  const id=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
