    sheet('Rentabilidad',[['Producto','Variante','Canal','Estado','Costo unitario COP','Precio actual COP','Precio sugerido COP','Resultado por unidad COP','Margen %','Objetivo %','Tipo de objetivo','Equilibrio unidades mes','Datos faltantes','Base del precio'],...exportRecipes.flatMap(r=>(model.channels.length?model.channels:[{id:'',name:'Sin canal'}]).map(ch=>{const c=E.calculate(model,r,ch.id);return [r.name,r.size,ch.name,c.definitive?'Completo':'Pendiente',c.definitive?c.cost:null,r.currentPrice,c.definitive?Math.ceil(c.recommended):null,c.definitive?c.profit:null,c.definitive?c.margin:null,r.targetPercent,r.marginMode==='margin'?'Margen sobre ventas':'Recargo sobre costos',c.breakEven,c.missing.join(' · '),r.pricingBasis==='production'?'Producción; gastos mensuales separados':'Costo con reparto de gastos'];}))]);
