  async function enterPractice(){if(busy)return;if(!loaded)await load();if(!loaded)return;actualState={model,revision,viewedRevision,history,approved,tab,editing,selected,dirty,viewing,lastActor,basisPending};practice=true;practicePending=false;let saved;try{saved=JSON.parse(OracleDb.local.getItem('costing-practice')||'null');}catch{}try{model=E.validate(saved?.practiceVersion===1?saved.model:example());}catch{model=example();}revision=saved?.revision||0;history=saved?.history||[];dirty=false;viewing=false;editing=null;tab='analysis';selected=model.recipes[0]?.id||'';render();notice('Ejemplo para practicar. Aquí no se escribe en tu cuenta.');}
